def solve(inputs: dict) -> float:
    M = inputs.get('M')
    if M is None:
        M = [[10, 6], [22, 22]]
    n = inputs.get('n', inputs.get('power', 30))
    mod = inputs.get('mod', 217322)
    size = len(M)
    def matmul(A, B):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                aik = A[i][k]
                if aik:
                    for j in range(size):
                        C[i][j] = (C[i][j] + aik * B[k][j]) % mod
        return C
    R = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    A = [[x % mod for x in row] for row in M]
    while n > 0:
        if n & 1:
            R = matmul(R, A)
        A = matmul(A, A)
        n >>= 1
    return float(sum(sum(row) for row in R) % mod)

